contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address recipient) public payable {
        require(caller != address(0), "caller zero");
        require(recipient != address(0), "recipient zero");

        uint256 preBalance = address(c).balance;

        bool ownerCall;
        if (caller == c.owner()) {
            ownerCall = true;
            c.withdrawAll(recipient);
        } else {
            ownerCall = false;
            try c.withdrawAll(recipient) {
                ownerCall = true;
            } catch {
                ownerCall = false;
            }
        }

        if (ownerCall) {
            assert(address(c).balance == 0);
        } else {
            assert(address(c).balance == preBalance);
        }
    }

    receive() external payable {}
}

